const now = new Date();
const currentMonth = now.getMonth();

const monthMapping = [
  { month: 10, name: '1st November', column: 'I' },
  { month: 11, name: '2nd December', column: 'J' },
  { month: 0, name: '3rd January', column: 'K' },
  { month: 1, name: '4th - Febraury', column: 'L' },
  { month: 2, name: '5th - March', column: 'M' },
  { month: 3, name: '6th - April', column: 'N' },
  { month: 4, name: '7th - May', column: 'O' },
  { month: 5, name: '8th - June', column: 'P' },
  { month: 6, name: '9th - July', column: 'Q' },
  { month: 7, name: '10th - August', column: 'R' },
  { month: 8, name: '11th - September', column: 'S' }
];

const currentMonthConfig = monthMapping.find(m => m.month === currentMonth);

if (!currentMonthConfig) {
  console.log('Month not in payment schedule');
  return [{ json: { 
    status: 'skip',
    message: 'Current month not in payment schedule'
  }}];
}

console.log('=== WORKFLOW INITIALIZED ===');
console.log('Month:', currentMonthConfig.name);
console.log('Column:', currentMonthConfig.column);
console.log('Days: 1, 3, 5, 7, 9');

return [{ json: {
  status: 'proceed',
  monthName: currentMonthConfig.name,
  monthColumn: currentMonthConfig.column,
  messageDays: [1, 3, 5, 7, 9]
}}];

