// Get month configuration from previous node
const monthName = $('Split Into Days2').item.json.monthName;
const monthColumn = $('Split Into Days2').item.json.monthColumn;
const currentDay = $('Split Into Days2').item.json.dayNumber;

// ==============================================
// HELPER FUNCTIONS
// ==============================================

function getPhoneNumber(row) {
  // Try different possible column names (with and without spaces)
  const possibleKeys = [
    'Number', 'Number ', 'number', 'number ',
    'Phone', 'Phone ', 'phone', 'phone ',
    'Phone Number', 'Phone Number ', 'Mobile', 'Mobile ', 'mobile', 'mobile '
  ];

  for (const key of possibleKeys) {
    if (row[key] !== undefined && row[key] !== null && String(row[key]).trim() !== '') {
      return String(row[key]).trim();
    }
  }

  return null;
}

function cleanPhoneNumber(number) {
  if (!number) return null;

  // Convert to string and remove all non-digit characters
  let cleaned = String(number).replace(/\D/g, '');

  // Check if we have at least 10 digits
  if (cleaned.length < 10) return null;

  // Handle Indian numbers starting with 0
  if (cleaned.startsWith('0')) {
    cleaned = '91' + cleaned.substring(1);
  }

  // Add country code if missing
  if (!cleaned.startsWith('91') && cleaned.length === 10) {
    cleaned = '91' + cleaned;
  }

  return cleaned;
}

function isPaymentCompleted(status) {
  if (!status) return false;
  const statusStr = String(status).toLowerCase().trim();
  if (statusStr.includes('compl') && !statusStr.includes('not')) return true;
  return false;
}

function calculateMonthlyPayment(scheme, value) {
  try {
    const schemeNum = parseFloat(scheme);
    const valueNum = parseFloat(value);
    if (isNaN(schemeNum) || isNaN(valueNum) || schemeNum === 0) return 0;
    return Math.round(valueNum / schemeNum);
  } catch (error) {
    return 0;
  }
}

// Helper to get value from row (handles trailing spaces)
function getRowValue(row, ...keys) {
  for (const key of keys) {
    // Try with and without trailing space
    if (row[key] !== undefined && row[key] !== null) return row[key];
    if (row[key + ' '] !== undefined && row[key + ' '] !== null) return row[key + ' '];
  }
  return null;
}

// ==============================================
// MAIN PROCESSING LOGIC
// ==============================================

const customersToMessage = [];
const errors = [];
let processedRows = 0;
let skippedRows = 0;
let alreadyCompleted = 0;
let totalMessages = 0;

const allItems = $input.all();

// Debug: Log available columns on first day
if (allItems.length > 0 && currentDay === 1) {
  console.log('=== AVAILABLE COLUMNS ===');
  const columns = Object.keys(allItems[0].json);
  console.log(columns.join(', '));
  console.log('\n=== FIRST ROW DATA SAMPLE ===');
  const firstRow = allItems[0].json;
  console.log('Name:', firstRow['Name']);
  console.log('Number (with space):', firstRow['Number ']);
  console.log('Value (with space):', firstRow['Value ']);
  console.log('Receipt No:', firstRow['Receipt No']);
}

// Process each row from Google Sheets
for (const item of allItems) {
  try {
    const row = item.json;
    const rowIndex = row.row_number || (item.index + 2);

    // Extract ALL customer details (handling trailing spaces)
    const receiptNo = getRowValue(row, 'Receipt No');
    const scheme = getRowValue(row, 'Scheme');
    const value = getRowValue(row, 'Value');
    const name = getRowValue(row, 'Name');
    const number = getPhoneNumber(row);
    const secondaryNumber = getRowValue(row, 'Secondary Number') || '';
    const type = getRowValue(row, 'Type') || '12 Months';
    const district = getRowValue(row, 'District');

    // Get payment status for CURRENT MONTH ONLY (handle spaces in month names)
    let currentMonthPaymentStatus = row[monthName];
    if (!currentMonthPaymentStatus) {
      // Try with trailing space
      currentMonthPaymentStatus = row[monthName + ' '];
    }

    // SKIP if already completed
    if (isPaymentCompleted(currentMonthPaymentStatus)) {
      alreadyCompleted++;
      processedRows++;
      continue;
    }

    // Validate essential data
    const trimmedName = name ? String(name).trim() : null;
    if (!trimmedName || trimmedName === '') {
      skippedRows++;
      errors.push({ 
        row: rowIndex, 
        error: 'Missing name', 
        data: { name: row['Name'], number }
      });
      continue;
    }

    if (!number || number === '') {
      skippedRows++;
      errors.push({ 
        row: rowIndex, 
        error: 'Missing phone number', 
        data: { name: trimmedName, number, rawNumber: row['Number '] }
      });
      continue;
    }

    if (!scheme || !value) {
      skippedRows++;
      errors.push({ 
        row: rowIndex, 
        error: 'Missing scheme or value', 
        data: { name: trimmedName, scheme, value }
      });
      continue;
    }

    // Clean and validate PRIMARY phone number
    const cleanedNumber = cleanPhoneNumber(number);
    if (!cleanedNumber || cleanedNumber.length < 10) {
      skippedRows++;
      errors.push({ 
        row: rowIndex, 
        error: 'Invalid phone number', 
        data: { name: trimmedName, number, cleaned: cleanedNumber }
      });
      continue;
    }

    // Calculate monthly payment amount
    const monthlyAmount = calculateMonthlyPayment(scheme, value);
    if (monthlyAmount === 0) {
      skippedRows++;
      errors.push({ 
        row: rowIndex, 
        error: 'Cannot calculate amount', 
        data: { name: trimmedName, scheme, value }
      });
      continue;
    }

    // Clean secondary number if present
    const cleanedSecondaryNumber = secondaryNumber && String(secondaryNumber).trim() !== '' 
      ? cleanPhoneNumber(secondaryNumber) 
      : '';

    // Create base customer data object
    const baseCustomerData = {
      Scheme: scheme,
      Value: value,
      Name: trimmedName,
      receiptNo: receiptNo || 'N/A',
      type: type,
      district: district ? String(district).trim() : 'N/A',
      amount: monthlyAmount,
      monthName: monthName,
      monthColumn: monthColumn,
      currentPaymentStatus: currentMonthPaymentStatus || 'Empty',
      rowNumber: rowIndex,
      messageDay: currentDay,
      timestamp: new Date().toISOString()
    };

    // Add PRIMARY number message
    customersToMessage.push({
      ...baseCustomerData,
      Number: cleanedNumber,
      numberType: 'primary'
    });
    totalMessages++;

    // Add SECONDARY number message if valid
    if (cleanedSecondaryNumber && cleanedSecondaryNumber.length >= 10) {
      customersToMessage.push({
        ...baseCustomerData,
        Number: cleanedSecondaryNumber,
        numberType: 'secondary'
      });
      totalMessages++;
    }

    processedRows++;

  } catch (error) {
    skippedRows++;
    errors.push({ 
      row: item.index + 2, 
      error: 'Processing error: ' + error.message,
      stack: error.stack
    });
  }
}

// ==============================================
// SUMMARY LOGGING
// ==============================================

console.log('\n=== PROCESSING SUMMARY ===');
console.log(`Day: ${currentDay} | Month: ${monthName}`);
console.log(`Processed: ${processedRows}`);
console.log(`Total Messages: ${totalMessages}`);
console.log(`Already Completed: ${alreadyCompleted}`);
console.log(`Errors/Skipped: ${skippedRows}`);
console.log(`To Message: ${customersToMessage.length}`);

if (errors.length > 0) {
  console.log('\n=== ERRORS (First 5) ===');
  errors.slice(0, 5).forEach(err => {
    console.log(`Row ${err.row}: ${err.error}`);
    if (err.data) {
      console.log(`  Data: ${JSON.stringify(err.data)}`);
    }
  });
  if (errors.length > 5) {
    console.log(`... and ${errors.length - 5} more errors`);
  }
}

if (customersToMessage.length > 0) {
  console.log('\n=== CUSTOMERS TO MESSAGE (First 5) ===');
  customersToMessage.slice(0, 5).forEach(c => {
    console.log(`- ${c.Name} (Receipt: ${c.receiptNo}) - ${c.numberType}`);
    console.log(`  Number: ${c.Number}`);
    console.log(`  Amount: ₹${c.amount}`);
    console.log(`  Scheme: ${c.Scheme}, Value: ${c.Value}`);
  });
}

// ==============================================
// RETURN DATA TO NEXT NODE
// ==============================================

if (customersToMessage.length === 0) {
  return [{ json: { 
    status: 'no_pending',
    monthName: monthName,
    messageDay: currentDay,
    processedRows: processedRows,
    alreadyCompleted: alreadyCompleted,
    skippedRows: skippedRows,
    errors: errors
  }}];
}

return customersToMessage.map(customer => ({ 
  json: customer 
}));

